(function () {
  'use strict';
  const chunkSet = {"title":"Author's Purpose","topic":"Reading Comprehension","questions":[{"id":"reading-comprehension-authors-purpose-q0101","version":3,"contentHash":"sha256:0f5c5e677a6a1e0ff370ba1af4deb32c6d3108649e4187b7a8b206d722a1af67","question":"Read the passage. Grade 4 foundation passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["The nurse checked the first-aid supplies after lunch.","They placed blue bins in classrooms and reminded students to use both sides of paper.","The passage avoids the topic after the first sentence.","The passage gives no examples or details."],"correct":1,"studyAid":{"definition":"Persuasive writing uses reasons and evidence to convince the reader to believe or do something. An author often provides successful examples to show why an idea is helpful.","example":"Persuasive: 'We should walk to school because it helps the planet.' Informative: 'Walking to school takes ten minutes.'","strategyClue":"Look for sentences that describe a positive action or result; authors use these to prove that their suggested solution is effective.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They placed blue bins in classrooms and reminded students to use both sides of paper. This sentence provides specific evidence of a successful action taken to solve a problem, which supports the author's argument that these efforts work.","incorrect":[{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This sentence is not in the passage and does not relate to the author's point about recycling efforts."},"",{"choice":"The passage avoids the topic after the first sentence.","category":"misreading the text","reason":"The passage actually provides multiple details, like using both sides of paper and ordering fewer boxes, to support the recycling claim."},{"choice":"The passage gives no examples or details.","category":"incorrect text analysis","reason":"The passage includes specific actions like using blue bins and printing on both sides to show how the recycling program functions."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":101,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0102","version":3,"contentHash":"sha256:67615898f76ac52f1147bda37d75ddd6e9fe5fe910178b92c34cc9ed8a3832a2","question":"Read the passage. Grade 4 foundation passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich audience would most likely find this passage useful?","choices":["readers studying a recipe for dessert","readers looking for a fantasy story with magic","readers who want to learn about the topic","readers trying to learn a new song"],"correct":2,"studyAid":{"definition":"To identify the intended audience, look for the passage's main purpose (inform, entertain, or persuade) and the specific facts or details provided.","example":"An article about space travel is for science lovers; a list of steps to build a birdhouse is for someone completing a project.","strategyClue":"Ask yourself: 'What is this passage mostly about?' and 'Who would actually need this information?' Match the subject matter of the text to the needs of the reader.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides informational details about a local history museum exhibit, which serves the purpose of educating readers interested in facts and historical content.","incorrect":[{"choice":"readers studying a recipe for dessert","category":"wrong content type","reason":"The passage describes a museum exhibit with historical tools and recordings, which does not provide ingredients or cooking instructions needed for a recipe."},{"choice":"readers looking for a fantasy story with magic","category":"wrong literary genre","reason":"The passage focuses on real-world history, elders, and physical museum artifacts, rather than imaginary worlds, magical creatures, or supernatural events."},"",{"choice":"readers trying to learn a new song","category":"wrong instructional purpose","reason":"While the passage mentions recordings, it describes oral histories of a town, not musical notes or lyrics required for someone trying to learn a song."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":102,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0103","version":3,"contentHash":"sha256:4f2f4a2b7655cf86f484ec2c846f8a12dd3dd2190dc8be35f481ebbbb76eaeca","question":"Read the passage. Grade 4 foundation passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to confuse readers about the topic","to tell a made-up adventure with a surprising ending","to list unrelated facts without a main point","to explain how testing improved a robot"],"correct":3,"studyAid":{"definition":"An author's main purpose is the primary reason they wrote the text, which is usually to inform, persuade, entertain, or explain a process.","example":"Inform: A book about space facts. Persuade: An essay saying we should recycle. Explain: A recipe for cookies.","strategyClue":"Look at the sentences in the text and ask yourself: 'Are these facts, opinions, or steps in a process?' If you see a sequence of actions like 'tested' and 'adjusted,' the goal is likely to explain a process.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how testing improved a robot. The passage describes specific steps the club members took—testing, adjusting code, and tracking results—to show the reader the progression of the robot's success.","incorrect":[{"choice":"to confuse readers about the topic","category":"incorrect purpose identification","reason":"Authors write to share information clearly, not to confuse the reader. The passage provides logical steps rather than confusing or scattered information."},{"choice":"to tell a made-up adventure with a surprising ending","category":"wrong genre/purpose","reason":"This is an informational passage about a process. It lacks fictional elements like characters going on an adventure or a dramatic, surprising plot twist."},{"choice":"to list unrelated facts without a main point","category":"lack of coherence","reason":"The sentences are clearly linked by the goal of improving the robot. The facts are related to the testing process, not scattered or unrelated."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":103,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0104","version":3,"contentHash":"sha256:c64c8bb04da513806464aed7ef165f1c5c17565377c245b803ce9ed4fab588ca","question":"Read the passage. Grade 4 foundation passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["The cart offered fruit, yogurt, and whole-grain muffins near the front door.","The science lab received new magnifying glasses.","The passage avoids the topic after the first sentence.","The passage gives no examples or details."],"correct":0,"studyAid":{"definition":"Persuasive writing uses evidence, facts, and reasons to convince the reader that a certain idea or action is positive.","example":"To persuade others that recess is important, include facts about student health or test scores.","strategyClue":"Look for the sentence that provides a concrete detail that makes the school's breakfast program sound helpful and beneficial to the community.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The cart offered fruit, yogurt, and whole-grain muffins near the front door. This sentence provides specific evidence of a successful, positive program that helps the community, which aligns with the author's argument that schools should support such efforts.","incorrect":["",{"choice":"The science lab received new magnifying glasses.","category":"irrelevant information","reason":"This information is not mentioned in the passage and does not help support the author's opinion about breakfast carts."},{"choice":"The passage avoids the topic after the first sentence.","category":"factual error","reason":"This is incorrect because the entire passage continues to provide details about the breakfast cart and why it is a good idea."},{"choice":"The passage gives no examples or details.","category":"factual error","reason":"The author actually provides specific examples of the food items served to show that the program is helpful and well-organized."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":104,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0105","version":3,"contentHash":"sha256:e979ef97fecfa158ab0408b9874477634a2ca62f1d586b543dc2650b4a7942f6","question":"Read the passage. Grade 4 foundation passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich audience would most likely find this passage useful?","choices":["readers looking for a fantasy story with magic","people who care about outdoor spaces","readers studying a recipe for dessert","readers trying to learn a new song"],"correct":1,"studyAid":{"definition":"Identifying the target audience means determining who would benefit most from the information or story being presented.","example":"A book about planets is for science students; a cookbook is for people learning to cook; a map is for travelers.","strategyClue":"List the main nouns and actions found in the text, then ask yourself: 'Who would spend time reading about these specific things?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: people who care about outdoor spaces. The passage provides descriptive details about a park, trail markers, and a hiking path, which directly relates to the interests and activities of outdoor enthusiasts.","incorrect":[{"choice":"readers looking for a fantasy story with magic","category":"mismatched genre","reason":"This passage is factual and describes real-world park features. It lacks elements of fantasy, magic, or imaginary creatures."},"",{"choice":"readers studying a recipe for dessert","category":"irrelevant topic","reason":"The passage discusses park trail infrastructure like benches and plaques, not food, ingredients, or cooking instructions."},{"choice":"readers trying to learn a new song","category":"irrelevant purpose","reason":"There is no mention of rhythm, lyrics, musical notes, or singing in this text about park trail improvements."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":105,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0106","version":3,"contentHash":"sha256:1702dcf5cd5d1f92823f4ccc099d75800b72493ba07b9b6bb5f572820454803c","question":"Read the passage. Grade 4 developing passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong. These details show that students used careful daily routines to help a garden grow. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to list unrelated facts without a main point","to tell a made-up adventure with a surprising ending","to explain how students cared for a garden","to confuse readers about the topic"],"correct":2,"studyAid":{"definition":"The author's purpose is the reason why someone writes a piece of text: usually to inform, persuade, or entertain.","example":"An encyclopedia entry informs, a persuasive essay tries to change your mind, and a comic book is written to entertain.","strategyClue":"Look at the key details in the passage. Ask yourself: 'Are these details telling a story, teaching me how to do something, or trying to convince me of an opinion?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students cared for a garden. The text provides a logical series of steps, such as watering, measuring, and managing shade, to show the specific process the class followed.","incorrect":[{"choice":"to list unrelated facts without a main point","category":"missing central theme","reason":"The sentences in this passage are all connected to the central topic of gardening. They are not random facts but rather a focused description of a specific process."},{"choice":"to tell a made-up adventure with a surprising ending","category":"incorrect text type","reason":"This passage is informational, not narrative. It describes real, expected tasks in a garden rather than telling a story with fictional characters or plot twists."},"",{"choice":"to confuse readers about the topic","category":"misidentifying author intent","reason":"An author's purpose is to communicate clearly. This text uses step-by-step details to help the reader learn, not to hide information or make the topic difficult to understand."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":106,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0107","version":3,"contentHash":"sha256:3c8e7bf9a69b898ec5ce80f9bf253e998f5b500054cea69b13c6048d01ea0192","question":"Read the passage. Grade 4 developing passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books. These details show that student volunteers organized books and labels to make the library easier to use. The author presents the steps and results so readers understand how the process works.\n\nWhich clue best shows that the author wants to explain?","choices":["The passage gives no examples or details.","The cafeteria served tomato soup on Thursday.","The passage avoids the topic after the first sentence.","They sorted returned books by call number before placing them on shelves."],"correct":3,"studyAid":{"definition":"Expository writing explains a process or topic by providing clear steps, examples, and logical details that help the reader understand how or why something happens.","example":"Explanation of a process: 'First, gather your ingredients. Next, stir the bowl until smooth.' (This explains the 'how').","strategyClue":"Look for sentences that describe actions or sequences. An author who wants to 'explain' will provide concrete details that show the reader the steps or reasons behind the main idea.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This sentence provides a specific, step-by-step detail about how the students completed their task, which helps the reader understand the process of organizing the library.","incorrect":[{"choice":"The passage gives no examples or details.","category":"factual accuracy","reason":"This is incorrect because the passage is full of details, such as sorting books by call number and making bright shelf labels, to show exactly what the volunteers did."},{"choice":"The cafeteria served tomato soup on Thursday.","category":"irrelevant information","reason":"This sentence mentions a topic completely unrelated to the library or the volunteers, so it cannot explain the author's purpose in this passage."},{"choice":"The passage avoids the topic after the first sentence.","category":"text evidence","reason":"The author stays on topic throughout the entire passage, continuing to describe the volunteers' actions and the positive results of their work."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":107,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0108","version":3,"contentHash":"sha256:7024b08161df50ce6351a885600d78e227527dfe209fbdd8a815099c865ae530","question":"Read the passage. Grade 4 developing passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose. These details show that a science club collected and reused rainwater to care for plants. The author presents the steps and results so readers understand how the process works.\n\nWhich audience would most likely find this passage useful?","choices":["readers who want to learn about the topic","readers looking for a fantasy story with magic","readers studying a recipe for dessert","readers trying to learn a new song"],"correct":0,"studyAid":{"definition":"To identify a passage's intended audience, look at the subject matter and the author's purpose. Informational texts are written for people interested in learning facts, 'how-to' procedures, or real-world explanations.","example":"A guide on how to build a birdhouse is for someone who enjoys woodworking. A news report about a local park opening is for someone who wants to know about community events.","strategyClue":"Ask yourself: 'What is the main point of this text?' Once you define the topic, think about whether that topic is for entertainment, instruction, or musical performance.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual information about collecting rainwater for plants, which is a process focused on science and gardening rather than creative fiction, culinary arts, or music.","incorrect":["",{"choice":"readers looking for a fantasy story with magic","category":"wrong genre","reason":"The passage contains real-world facts about water conservation and plants. Fantasy stories require fictional elements like magic, which are not present here."},{"choice":"readers studying a recipe for dessert","category":"wrong topic","reason":"This passage explains how to gather rainwater for garden plants. It does not provide ingredients or cooking instructions for making sweet foods."},{"choice":"readers trying to learn a new song","category":"wrong purpose","reason":"The text describes a scientific process for saving water. It does not include musical notes, lyrics, or rhythms needed to learn a song."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":108,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0109","version":3,"contentHash":"sha256:525a7237801675406e5d1e2530e0c9b31e8004805a9141dc7e02cebc2fe03549","question":"Read the passage. Grade 4 developing passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey. These details show that student reporters gathered facts and published school news. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to tell a made-up adventure with a surprising ending","to explain how students made a newspaper","to list unrelated facts without a main point","to confuse readers about the topic"],"correct":1,"studyAid":{"definition":"An author's purpose is their main reason for writing a text, such as to inform, explain, entertain, or persuade.","example":"A cookbook explains how to bake bread. A fable entertains with a moral lesson. A poster persuades you to vote.","strategyClue":"Look at the verbs used in the text (interviewed, wrote, checked, published) and ask yourself if the author is telling a story, giving instructions, or trying to convince you of an opinion.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students made a newspaper. The passage explicitly describes the steps the reporters took, such as interviewing, writing, and checking facts, to show the process of creating the newspaper.","incorrect":[{"choice":"to tell a made-up adventure with a surprising ending","category":"incorrect genre","reason":"The passage is factual and describes real tasks like checking facts. It does not contain fictional plot elements or a narrative story arc."},"",{"choice":"to list unrelated facts without a main point","category":"missing main idea","reason":"The facts provided are all connected to the central topic of creating a school newspaper, making the information very organized rather than unrelated."},{"choice":"to confuse readers about the topic","category":"purpose mismatch","reason":"The author's goal is to inform and help readers understand the process, so the writing is intentionally clear and straightforward."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":109,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0110","version":3,"contentHash":"sha256:ebb78ce14ad8143c5ea196ca59278ead5de0c9307c627cea8190adb6af4cb1b4","question":"Read the passage. Grade 4 developing passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash. These details show that families cleaned litter from the beach and encouraged visitors to keep it clean. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["The passage avoids the topic after the first sentence.","The town band played a concert in the park.","They filled ten bags with plastic wrappers, bottle caps, and broken fishing line.","The passage gives no examples or details."],"correct":2,"studyAid":{"definition":"Persuasive writing uses specific evidence and reasons to convince the reader that an action or opinion is valuable.","example":"A writer says we need a new playground (opinion) because the old one has broken swings and rusted slides (evidence).","strategyClue":"Look for the sentence that provides a concrete fact or specific result, as these details are what make an argument strong and believable.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides specific evidence of the action taken, highlighting the impact of the effort and supporting the author's purpose to show that these activities solve community problems.","incorrect":[{"choice":"The passage avoids the topic after the first sentence.","category":"factual error","reason":"This is incorrect because the entire passage continues to focus on the cleanup efforts, the signs posted, and the community benefits."},{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This information is not mentioned in the text at all; you must look for clues that exist within the passage to support the author's argument."},"",{"choice":"The passage gives no examples or details.","category":"evidence oversight","reason":"The passage actually provides several clear details about the litter removed, the actions taken by volunteers, and the reason for the cleanup."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":110,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0111","version":3,"contentHash":"sha256:d13ebb3e24e4adb94e8e3adae2f8847bceb7a41c76b3f47c509dc4611d58f51f","question":"Read the passage. Grade 4 developing passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors. These details show that a safety officer taught students important bike safety habits. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich audience would most likely find this passage useful?","choices":["readers trying to learn a new song","readers looking for a fantasy story with magic","readers studying a recipe for dessert","readers who want to learn about the topic"],"correct":3,"studyAid":{"definition":"To identify the intended audience, look for the purpose of the text: Is it to inform, entertain, or persuade? Match that purpose to the type of reader who would benefit most from the information.","example":"A book about planets is for science learners; a funny comic book is for people who want entertainment; a cooking guide is for people who want to prepare food.","strategyClue":"Ask yourself: 'What is the main subject of this text?' Then, choose the reader whose goal matches the information provided in that subject.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual information and advice about bike safety, which is useful for someone seeking knowledge on that specific subject.","incorrect":[{"choice":"readers trying to learn a new song","category":"mismatched topic","reason":"The passage is about bicycle safety habits, not music or singing, so it would not help someone trying to learn a song."},{"choice":"readers looking for a fantasy story with magic","category":"mismatched genre","reason":"Fantasy stories involve imaginary events and magic, while this passage contains realistic, factual information about community safety."},{"choice":"readers studying a recipe for dessert","category":"mismatched purpose","reason":"A recipe provides instructions for cooking food. This passage teaches safety habits, so it does not contain the information needed for baking or cooking."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":111,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0112","version":3,"contentHash":"sha256:124ee258617ae6da2705e044654921a1b3d0b1ea11096a72f02b8dbb8be3107e","question":"Read the passage. Grade 4 developing passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes. These details show that transportation planners improved bus service so people could reach useful places. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to explain how new bus routes helped a neighborhood","to tell a made-up adventure with a surprising ending","to list unrelated facts without a main point","to confuse readers about the topic"],"correct":0,"studyAid":{"definition":"An author's purpose is their reason for writing: to inform (explain facts), to persuade (convince others), or to entertain (tell a story).","example":"An encyclopedia entry informs, an advertisement persuades, and a fairy tale entertains.","strategyClue":"Ask yourself: Does this passage tell a story, describe how something works, or try to convince me of an opinion? Look for signal words like 'because' or 'results' to identify an explanation.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how new bus routes helped a neighborhood. The passage identifies a specific problem (transportation), describes the action taken by planners, and highlights the resulting benefit to the community, which matches the author's purpose of explaining a process.","incorrect":["",{"choice":"to tell a made-up adventure with a surprising ending","category":"incorrect text type","reason":"This is a factual, informational passage, not a story. There are no characters or plot twists to suggest a narrative adventure."},{"choice":"to list unrelated facts without a main point","category":"lacks main idea","reason":"The passage is organized around a central topic (bus routes) and a clear result (improved service), so the details are related, not random."},{"choice":"to confuse readers about the topic","category":"incorrect author goal","reason":"Authors write to inform, persuade, or entertain. A good author tries to be as clear as possible, not to purposely cause confusion."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":112,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0113","version":3,"contentHash":"sha256:83b07a9a244a3c986ef72c2829034c9e817978c7aca2ffd26bad2d8e4ff22ecb","question":"Read the passage. Grade 4 developing passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began. These details show that actors and crew members cooperated to get a play ready. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich clue best shows that the author wants to describe?","choices":["A math poster showed different kinds of triangles.","Actors practiced lines while stage crew members painted scenery and tested lights.","The passage avoids the topic after the first sentence.","The passage gives no examples or details."],"correct":1,"studyAid":{"definition":"Descriptive writing uses specific details, actions, and examples to help the reader create a mental picture of a scene or event.","example":"Instead of saying 'The dog was loud,' a descriptive sentence would be 'The dog barked rhythmically at the mail carrier, wagging his tail excitedly.'","strategyClue":"Look for the sentence that lists concrete tasks or visible actions related to the main topic. Eliminate choices that describe things not mentioned in the text or that claim the author didn't provide any information.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence provides vivid, specific examples of actions taken by the crew and cast, allowing the reader to visualize the collaborative work involved in preparing for the play.","incorrect":[{"choice":"A math poster showed different kinds of triangles.","category":"irrelevant information","reason":"The passage is about a play, not geometry. This choice describes a topic completely unrelated to the theater setting described in the text."},"",{"choice":"The passage avoids the topic after the first sentence.","category":"factual error","reason":"This is incorrect because the entire passage continues to focus on the play. Every sentence after the first one provides more details about how the team prepared."},{"choice":"The passage gives no examples or details.","category":"misreading text","reason":"The text is actually full of details, such as painting scenery, testing lights, and fixing a tangled rope. These specific actions show that the author is clearly providing examples."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":113,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0114","version":3,"contentHash":"sha256:62ed9cb1c1e5bf9a178bcd49415736ed6a234d8e8ee6708fc559eb64c359be16","question":"Read the passage. Grade 4 developing passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds. These details show that cafeteria food scraps were collected and turned into compost for flowers. The author presents the steps and results so readers understand how the process works.\n\nWhich audience would most likely find this passage useful?","choices":["readers studying a recipe for dessert","readers looking for a fantasy story with magic","readers who want to learn about the topic","readers trying to learn a new song"],"correct":2,"studyAid":{"definition":"To identify the intended audience, look for the passage's purpose: is it to entertain, to teach facts, or to give instructions?","example":"A cookbook is for cooks, a fable is for readers wanting a moral lesson, and a science report is for someone interested in nature.","strategyClue":"Ask yourself: 'What is the main topic of this writing, and who would care about learning those specific facts?' Match the content to the goal of the reader.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual, step-by-step information about a composting process, which is exactly what someone looking to learn about a specific subject would read.","incorrect":[{"choice":"readers studying a recipe for dessert","category":"irrelevant subject matter","reason":"The passage describes food scraps for compost, not ingredients for a dessert. A recipe would require a list of items and instructions for cooking."},{"choice":"readers looking for a fantasy story with magic","category":"wrong genre","reason":"Fantasy stories feature imaginary characters and magical events. This passage is non-fiction, describing a real-world environmental process."},"",{"choice":"readers trying to learn a new song","category":"mismatched content type","reason":"A passage about composting does not contain lyrics, musical notes, or rhythms. You would look for a songbook or music sheet to learn a song."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":114,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0115","version":3,"contentHash":"sha256:8f959e810307a6911512bae69c64b5b6138b2ae90b7b53fe85608b6f87fe08b9","question":"Read the passage. Grade 4 developing passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights. These details show that science students recorded weather measurements and used them to find patterns. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to confuse readers about the topic","to tell a made-up adventure with a surprising ending","to list unrelated facts without a main point","to explain how students studied weather"],"correct":3,"studyAid":{"definition":"An author's purpose is the reason they wrote a text, usually to inform, entertain, describe, or persuade.","example":"An encyclopedia entry informs, a fairy tale entertains, and a recipe describes steps.","strategyClue":"Ask yourself: 'Why did the author provide these details?' Look at the text to see if it teaches you how to do something, tells a story, or tries to change your mind.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students studied weather. The passage details the specific measurements taken and the resulting observations to clarify the process the students followed.","incorrect":[{"choice":"to confuse readers about the topic","category":"incorrect purpose","reason":"The author provides clear, organized information about a science project. Confusing readers is not a logical goal for a descriptive passage."},{"choice":"to tell a made-up adventure with a surprising ending","category":"wrong text type","reason":"This passage is factual and informational. It describes a real-world activity rather than telling a fictional story with plot twists."},{"choice":"to list unrelated facts without a main point","category":"disorganized information","reason":"The facts provided are all related to the students' weather study, and they build toward a clear conclusion about tracking patterns."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":115,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0116","version":3,"contentHash":"sha256:7bf4334a57fe2cbe7e6472aad57a19746b1c5b3f7c9ceefdf77c7c5a64f54281","question":"Read the passage. Grade 4 developing passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper. These details show that a recycling team used bins and reminders to reduce paper waste. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["They placed blue bins in classrooms and reminded students to use both sides of paper.","The nurse checked the first-aid supplies after lunch.","The passage avoids the topic after the first sentence.","The passage gives no examples or details."],"correct":0,"studyAid":{"definition":"Persuasive writing tries to convince the reader to agree with an opinion or support an action by providing reasons, evidence, and logical details.","example":"Opinion: 'We should walk to school.' Evidence: 'It is good for our health and helps the environment.'","strategyClue":"Look for the sentence that provides a specific, positive example of a solution to the problem mentioned in the text; persuasive authors use these details to show why their position makes sense.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They placed blue bins in classrooms and reminded students to use both sides of paper. This sentence provides evidence of a positive action taken to solve a problem, which supports the author's argument that such efforts are beneficial and should be supported.","incorrect":["",{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This sentence is not related to the passage about recycling; it introduces a completely different topic that does not support the author's argument."},{"choice":"The passage avoids the topic after the first sentence.","category":"factual inaccuracy","reason":"The passage actually continues to discuss recycling throughout, providing details on how the goal was achieved and why the team's work is important."},{"choice":"The passage gives no examples or details.","category":"factual inaccuracy","reason":"The passage does provide specific examples, such as the use of blue bins and the instruction to use both sides of the paper, to show how recycling works."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":116,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0117","version":3,"contentHash":"sha256:2e2becdeba477341ea7e4c8650ea79dc95ddf13482a09688894f0381bbd3b11d","question":"Read the passage. Grade 4 developing passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories. These details show that museum workers created an exhibit that helped visitors learn local history. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich audience would most likely find this passage useful?","choices":["readers looking for a fantasy story with magic","readers who want to learn about the topic","readers studying a recipe for dessert","readers trying to learn a new song"],"correct":1,"studyAid":{"definition":"To identify the intended audience, determine the author's purpose: is the text meant to teach facts, tell an entertaining story, or give instructions?","example":"A textbook explains science facts (for students), a cookbook lists steps for a meal (for cooks), and a fable teaches a lesson (for story lovers).","strategyClue":"Identify the main topic of the text and ask yourself, 'What kind of information is being shared?' Then, match that content to the goal of the reader.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual information about a local history exhibit at a museum, which serves the purpose of educating readers on a specific subject.","incorrect":[{"choice":"readers looking for a fantasy story with magic","category":"genre mismatch","reason":"The passage describes real-life museum activities and historical facts, not magical creatures or made-up events found in fantasy literature."},"",{"choice":"readers studying a recipe for dessert","category":"content mismatch","reason":"The text discusses historical tools and local town records; it does not provide ingredients or instructions for cooking or baking."},{"choice":"readers trying to learn a new song","category":"purpose mismatch","reason":"While the passage mentions recordings, it is about history and museums, not musical notation, lyrics, or instructions on how to sing or play music."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":117,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0118","version":3,"contentHash":"sha256:7aca500165e8ef8d7876622c2319c612dbb8ada227a96b2872cd946120301b7e","question":"Read the passage. Grade 4 developing passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course. These details show that club members tested a robot, changed its code, and used notes to improve it. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to list unrelated facts without a main point","to tell a made-up adventure with a surprising ending","to explain how testing improved a robot","to confuse readers about the topic"],"correct":2,"studyAid":{"definition":"The author's purpose is the reason why they wrote the text, which is usually to inform, explain, persuade, or entertain.","example":"An encyclopedia entry informs, a manual explains how something works, a speech persuades an audience, and a novel entertains.","strategyClue":"Look at the beginning and the end of the passage to identify the main topic, then ask yourself if the author is telling a story, giving facts, or showing how a process is done.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how testing improved a robot. The passage provides a sequence of actions—testing, adjusting code, and taking notes—to show how the club achieved their goal, which defines an explanatory purpose.","incorrect":[{"choice":"to list unrelated facts without a main point","category":"disorganized information error","reason":"The facts in the passage are not unrelated; they all focus on the specific steps of testing and improving the robot, leading to a clear, central main idea."},{"choice":"to tell a made-up adventure with a surprising ending","category":"narrative fiction error","reason":"The passage describes a realistic process of testing and debugging, rather than a creative story with characters, plot twists, or a surprising climax."},"",{"choice":"to confuse readers about the topic","category":"unclear purpose error","reason":"Authors aim to be clear, not confusing. The passage uses logical steps to help the reader understand exactly how the robot was improved."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":118,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0119","version":3,"contentHash":"sha256:dfe31f806657597ea4e106c3d032985fbd59863c072ff6a77de242f1ff7c1677","question":"Read the passage. Grade 4 developing passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal. These details show that school leaders made breakfast easier for busy students to get. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["The passage gives no examples or details.","The science lab received new magnifying glasses.","The passage avoids the topic after the first sentence.","The cart offered fruit, yogurt, and whole-grain muffins near the front door."],"correct":3,"studyAid":{"definition":"Persuasive writing tries to convince the reader of an opinion by using reasons, facts, and evidence to support a claim.","example":"Statement: 'We should have recess every day.' Evidence: 'Playing outside helps students focus better in class.'","strategyClue":"Look for a sentence that provides a 'reason' why the program is a good idea. Persuasive authors use evidence to explain why something is beneficial or helpful.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The cart offered fruit, yogurt, and whole-grain muffins near the front door. This sentence provides a specific detail about the solution, which the author uses to build the argument that the breakfast program effectively solves a problem for busy students.","incorrect":[{"choice":"The passage gives no examples or details.","category":"factual error","reason":"This is incorrect because the passage provides several clear examples, such as the breakfast cart and the specific healthy foods offered."},{"choice":"The science lab received new magnifying glasses.","category":"irrelevant information","reason":"This detail is not found in the passage. When identifying an author's purpose, only use evidence that is actually written in the text."},{"choice":"The passage avoids the topic after the first sentence.","category":"misreading text","reason":"The entire passage remains focused on the breakfast cart and why it is a helpful effort, proving that the topic is not avoided."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":119,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0120","version":3,"contentHash":"sha256:6c854cc6398b003db0b7f2151a153cd369bd08290d8d0f43be02302ebd1d7892","question":"Read the passage. Grade 4 developing passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek. These details show that park rangers marked a trail so visitors could navigate and learn. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich audience would most likely find this passage useful?","choices":["people who care about outdoor spaces","readers looking for a fantasy story with magic","readers studying a recipe for dessert","readers trying to learn a new song"],"correct":0,"studyAid":{"definition":"An author's purpose and the intended audience match the subject matter of the text. To identify the audience, look at the topic and what kind of information is being provided.","example":"A book about space suits is for science fans; a book about baking cookies is for people interested in cooking.","strategyClue":"Look at the specific nouns and verbs in the passage (like 'trail', 'rangers', 'hikers', and 'bench') and ask yourself what activity involves these things.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: people who care about outdoor spaces. The passage provides descriptive details about park features like trails, signs, and benches, which directly interest someone planning a visit or learning about the outdoors.","incorrect":["",{"choice":"readers looking for a fantasy story with magic","category":"mismatched genre interest","reason":"This passage describes real-life objects like park signs and wooden benches. It contains no magical elements, dragons, or wizards that a fantasy reader would expect."},{"choice":"readers studying a recipe for dessert","category":"mismatched content type","reason":"A recipe needs ingredients and cooking instructions. Since this passage describes a forest trail, it does not provide the information needed to bake or make a dessert."},{"choice":"readers trying to learn a new song","category":"mismatched purpose","reason":"To learn a song, you need lyrics or musical notes. This passage contains factual descriptions of a park, not rhythms, melodies, or lyrics."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":120,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0121","version":3,"contentHash":"sha256:f8241b5d46771b84c4887b26a5025fb9fcf249b9a1fdc44c8f5f22495952728f","question":"Read the passage. Grade 4 challenge passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong. Because the passage connects actions with results, readers can see why daily care helped the school garden grow well. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to tell a made-up adventure with a surprising ending","to explain how students cared for a garden","to list unrelated facts without a main point","to confuse readers about the topic"],"correct":1,"studyAid":{"definition":"An author's purpose is their reason for writing: to inform, to persuade, to entertain, or to explain a process.","example":"An encyclopedia entry informs, a storybook entertains, and a recipe explains a process.","strategyClue":"Look at the actions mentioned in the text and ask yourself: 'Does this tell a story, convince me of something, or teach me how something works?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students cared for a garden. The text describes specific actions taken by the students, such as watering and monitoring sunlight, to show how these steps led to the growth of the garden.","incorrect":[{"choice":"to tell a made-up adventure with a surprising ending","category":"wrong text type","reason":"The passage describes factual actions and processes, not a fictional story or adventure with characters encountering a surprise."},"",{"choice":"to list unrelated facts without a main point","category":"lacks logical connection","reason":"The facts in the passage are all related to garden care, and they work together to create a clear main idea about how daily care helps plants grow."},{"choice":"to confuse readers about the topic","category":"unintended reader effect","reason":"The author organizes the steps in a logical way to help the reader learn about the process, rather than trying to make the subject matter harder to understand."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":121,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0122","version":3,"contentHash":"sha256:1b663a1561730013f7759b926b776c34274a00480ce1718ada6883ee69cd1f61","question":"Read the passage. Grade 4 challenge passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books. Because the passage connects actions with results, readers can see why student helpers organized the library so readers could find books faster. The author presents the steps and results so readers understand how the process works.\n\nWhich clue best shows that the author wants to explain?","choices":["The passage avoids the topic after the first sentence.","The cafeteria served tomato soup on Thursday.","They sorted returned books by call number before placing them on shelves.","The passage gives no examples or details."],"correct":2,"studyAid":{"definition":"An explanatory text provides facts, steps, or details to help the reader understand how something works or why something happened.","example":"An explanation of a science experiment (step 1, step 2), instructions for a board game, or describing how a plant grows.","strategyClue":"Look for sentences that describe a sequence of events or specific actions taken to achieve a goal, rather than sentences that just describe feelings or unrelated facts.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This sentence provides a specific, step-by-step detail about the process, which supports the author's goal of explaining how the students organized the library.","incorrect":[{"choice":"The passage avoids the topic after the first sentence.","reason":"This is incorrect because the entire passage continues to focus on the students' actions, such as sorting books and making labels, to explain the process."},{"choice":"The cafeteria served tomato soup on Thursday.","reason":"This statement is irrelevant and does not appear in the text provided. It does not help explain the process of organizing the library."},"",{"choice":"The passage gives no examples or details.","reason":"This is incorrect because the passage is full of specific examples, such as 'sorted returned books' and 'made bright shelf labels,' which serve as details to support the author's explanation."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":122,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0123","version":3,"contentHash":"sha256:a9af7533050aff44de04dbad01cbd70e61721b9d6c8adac0edf3c6d4e5fc9dce","question":"Read the passage. Grade 4 challenge passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose. Because the passage connects actions with results, readers can see why a rain barrel helped the club save water for plants. The author presents the steps and results so readers understand how the process works.\n\nWhich audience would most likely find this passage useful?","choices":["readers trying to learn a new song","readers looking for a fantasy story with magic","readers studying a recipe for dessert","readers who want to learn about the topic"],"correct":3,"studyAid":{"definition":"To determine a passage's target audience, identify the author's purpose and the main topic. Informational texts are meant for readers seeking facts, instructions, or explanations about real-world concepts.","example":"A manual is for people fixing a bike; a historical biography is for people learning about the past; a textbook is for students learning a subject.","strategyClue":"Identify the primary topic of the text first. Once you know what the passage is teaching, ask yourself who would care about that specific topic.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual, step-by-step information about collecting rainwater, which is an educational topic. Readers interested in learning how something works or how to save resources would find this useful.","incorrect":[{"choice":"readers trying to learn a new song","category":"mismatched instructional content","reason":"The passage discusses science and water conservation, not music or lyrics. Someone looking to learn a song would not find information about rainwater barrels helpful."},{"choice":"readers looking for a fantasy story with magic","category":"mismatched genre expectation","reason":"This passage is a factual account of a real-world activity. It lacks the imaginary characters, settings, or magical elements required for a fantasy story."},{"choice":"readers studying a recipe for dessert","category":"mismatched practical application","reason":"While the passage describes a process, it is about water usage for plants. It does not contain ingredients, measurements, or cooking instructions needed to prepare a dessert."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":123,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0124","version":3,"contentHash":"sha256:a0ffb1afc2fd4d43964e8d179aec716f597f7719294a8c77101239cba24127af","question":"Read the passage. Grade 4 challenge passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey. Because the passage connects actions with results, readers can see why the class newspaper gave students a careful way to share school news. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to explain how students made a newspaper","to tell a made-up adventure with a surprising ending","to list unrelated facts without a main point","to confuse readers about the topic"],"correct":0,"studyAid":{"definition":"An author's purpose is the reason why they wrote a piece of text, usually to inform, persuade, entertain, or explain.","example":"A recipe explains how to bake a cake. A fairy tale is written to entertain. A poster for a bake sale is written to persuade.","strategyClue":"Look at the beginning and the end of the paragraph. Ask yourself, 'What is the main topic, and what does the author want me to know about that topic?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students made a newspaper. The text focuses on the sequence of steps the students took, from interviewing to printing, and explains why they created the newspaper to share school news.","incorrect":["",{"choice":"to tell a made-up adventure with a surprising ending","category":"incorrect text type","reason":"This is a factual account of a school activity, not a fictional adventure story. There are no characters facing a dramatic plot twist or fantasy elements."},{"choice":"to list unrelated facts without a main point","category":"lacks logical structure","reason":"The sentences in the passage are clearly connected. They all center on the same topic: the process of creating a student newspaper."},{"choice":"to confuse readers about the topic","category":"misidentifying author intent","reason":"An author's purpose is to communicate clearly, not to cause confusion. The passage provides a logical, step-by-step look at how the newspaper was organized."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":124,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0125","version":3,"contentHash":"sha256:3b74dba901f0518b0f5ea20c90be8528fa66eecc778df99a7f93314e1dd60ba6","question":"Read the passage. Grade 4 challenge passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash. Because the passage connects actions with results, readers can see why the cleanup protected the beach by removing harmful litter. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["The town band played a concert in the park.","They filled ten bags with plastic wrappers, bottle caps, and broken fishing line.","The passage avoids the topic after the first sentence.","The passage gives no examples or details."],"correct":1,"studyAid":{"definition":"Persuasive writing tries to convince the reader to agree with an opinion by using reasons, facts, and specific examples to show why something is good or important.","example":"Persuasive: 'Everyone should plant a tree because it provides shade and cleans the air.' vs. Informative: 'Trees provide shade and clean the air.'","strategyClue":"Look for a sentence that provides concrete evidence or a strong reason supporting the author's viewpoint, rather than just stating a fact or describing a setting.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This clue shows the author is using specific, descriptive evidence of a successful cleanup effort to influence the reader's opinion that the beach needed cleaning and that the action was effective.","incorrect":[{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This sentence is not found in the passage and has nothing to do with the beach cleanup project described."},"",{"choice":"The passage avoids the topic after the first sentence.","category":"incorrect text analysis","reason":"The passage actually continues to discuss the cleanup process, the purpose of the signs, and why people should support such efforts, rather than ignoring the topic."},{"choice":"The passage gives no examples or details.","category":"incorrect text analysis","reason":"The passage provides many specific details, such as the ten bags of trash and the specific types of litter collected, to support the author's argument."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":125,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0126","version":3,"contentHash":"sha256:951d4fbc4cf1ed0b9064a9c8556199df0c1231fd8b238602f943b392f00258c3","question":"Read the passage. Grade 4 challenge passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors. Because the passage connects actions with results, readers can see why bike riders can prevent injuries by following safety rules. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich audience would most likely find this passage useful?","choices":["readers studying a recipe for dessert","readers looking for a fantasy story with magic","readers who want to learn about the topic","readers trying to learn a new song"],"correct":2,"studyAid":{"definition":"To identify the intended audience, look at the subject matter and the goal of the passage to determine who would gain the most value from the information provided.","example":"A guide on how to plant a garden is for someone starting a hobby; a newspaper report on a local fire is for community members seeking facts.","strategyClue":"Look for keywords in the text that describe a specific activity or problem, then ask yourself: 'Who would need help with this specific thing?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual information and safety tips regarding bicycle safety, which is useful for someone interested in learning how to stay safe while riding.","incorrect":[{"choice":"readers studying a recipe for dessert","category":"mismatched topic","reason":"This passage is about bicycle safety and community rules, not ingredients or instructions for making sweet foods."},{"choice":"readers looking for a fantasy story with magic","category":"wrong genre","reason":"The text focuses on real-world safety procedures and community problems, which does not fit the style of imaginative stories involving magic or supernatural events."},"",{"choice":"readers trying to learn a new song","category":"mismatched purpose","reason":"The passage contains advice and safety instructions for bikers, not lyrics, melodies, or musical notation."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":126,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0127","version":3,"contentHash":"sha256:6b066ab74f61671ec852bdec95a5214f4cf4d0400532e1a15af1bc944c1983df","question":"Read the passage. Grade 4 challenge passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes. Because the passage connects actions with results, readers can see why new bus routes made important places easier to reach. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to confuse readers about the topic","to tell a made-up adventure with a surprising ending","to list unrelated facts without a main point","to explain how new bus routes helped a neighborhood"],"correct":3,"studyAid":{"definition":"The author's purpose is the main reason why a text was written, such as to explain a process, tell a story, or persuade a reader.","example":"To inform: A textbook page about plants. To entertain: A fable about a fox. To explain: A set of instructions for building a toy.","strategyClue":"Ask yourself: 'Why did the author write this?' Look for words that show cause and effect, like 'because' and 'result,' to determine if the author is explaining a process.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how new bus routes helped a neighborhood. The passage details a specific change (new routes) and the resulting benefits (shorter wait times and better access to key locations), which identifies the author's purpose as informational.","incorrect":[{"choice":"to confuse readers about the topic","category":"incorrect intent","reason":"Authors write to share information clearly, not to cause confusion. This passage is organized logically to help readers understand the situation."},{"choice":"to tell a made-up adventure with a surprising ending","category":"wrong text type","reason":"This is a factual, informational passage, not a narrative story. It lacks characters, a plot, or an adventurous ending."},{"choice":"to list unrelated facts without a main point","category":"lack of coherence","reason":"The facts provided are all related to bus transportation and community access. They work together to support a central idea about how the new routes were useful."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":127,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0128","version":3,"contentHash":"sha256:7a3c1026b81563af2ff969fc0f82437a2d3f3445a05256a95f8fc452ede9c817","question":"Read the passage. Grade 4 challenge passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began. Because the passage connects actions with results, readers can see why many students worked together to prepare the school play. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich clue best shows that the author wants to describe?","choices":["Actors practiced lines while stage crew members painted scenery and tested lights.","A math poster showed different kinds of triangles.","The passage avoids the topic after the first sentence.","The passage gives no examples or details."],"correct":0,"studyAid":{"definition":"An author's purpose for using descriptive details is to help the reader create a mental picture or 'movie' of the scene in their mind.","example":"Instead of saying 'the room was messy,' an author might say 'papers were scattered across the floor and books were piled high on every chair.'","strategyClue":"Look for a sentence that describes what people were doing or what things looked like. A good descriptive clue will help you 'see' the action taking place.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence provides specific sensory details and descriptions of actions, which directly supports the author's purpose of helping the reader visualize the scene.","incorrect":["",{"choice":"A math poster showed different kinds of triangles.","category":"irrelevant information","reason":"This sentence mentions math concepts that are completely unrelated to the story about preparing a play."},{"choice":"The passage avoids the topic after the first sentence.","category":"incorrect text analysis","reason":"The entire passage remains focused on the play; the author continues to add details about the stage crew and the curtain throughout the paragraph."},{"choice":"The passage gives no examples or details.","category":"ignoring textual evidence","reason":"This is incorrect because the passage is filled with specific details like 'curtain rope,' 'painted scenery,' and 'tested lights' to help readers picture the scene."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":128,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0129","version":3,"contentHash":"sha256:8b040e78e03a6531d8c3b8d5a8ec15cd25e53b2efa5360a38a2f0f0a717cc94d","question":"Read the passage. Grade 4 challenge passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds. Because the passage connects actions with results, readers can see why composting changed cafeteria scraps into useful soil material. The author presents the steps and results so readers understand how the process works.\n\nWhich audience would most likely find this passage useful?","choices":["readers looking for a fantasy story with magic","readers who want to learn about the topic","readers studying a recipe for dessert","readers trying to learn a new song"],"correct":1,"studyAid":{"definition":"Informational texts are written to give the reader facts and explanations about real-world topics, processes, or people.","example":"A book about how clouds form (informational), a guide on how to build a birdhouse (informational), a novel about talking dragons (narrative/fantasy).","strategyClue":"Ask yourself what the passage is teaching: is it telling a story, teaching a skill, or explaining how a process works? Match that goal to the purpose of the audience.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual information about composting, which is a process, making it a perfect fit for someone seeking to learn how something works.","incorrect":[{"choice":"readers looking for a fantasy story with magic","category":"wrong text type","reason":"The passage is informational and describes a real-world process. It does not contain characters, spells, or magical events found in fantasy stories."},"",{"choice":"readers studying a recipe for dessert","category":"incorrect content purpose","reason":"While the passage mentions 'fruit peels,' it explains how to turn trash into soil, not how to cook or bake a dessert."},{"choice":"readers trying to learn a new song","category":"mismatched instructional goal","reason":"The text explains a scientific or environmental process. It does not provide musical notes, lyrics, or instructions on how to sing."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":129,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0130","version":3,"contentHash":"sha256:ee1d1643af223311603f9eba3143d61efb52968c8a88c3b27c2255481ea107f6","question":"Read the passage. Grade 4 challenge passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights. Because the passage connects actions with results, readers can see why students collected weather data to notice local patterns. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to list unrelated facts without a main point","to tell a made-up adventure with a surprising ending","to explain how students studied weather","to confuse readers about the topic"],"correct":2,"studyAid":{"definition":"An author's purpose is the reason they wrote a text, such as to explain how something works, to persuade, or to entertain.","example":"An explanation of the water cycle; a story about a dragon; a letter trying to get more playground equipment.","strategyClue":"Ask yourself: 'What is this passage mostly about?' and 'What information is the author giving me?' If the text describes a series of steps or facts, the purpose is likely to explain.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students studied weather. The passage describes a scientific process, detailing what the students tracked, how they measured it, and what they learned from their data.","incorrect":[{"choice":"to list unrelated facts without a main point","category":"lack of coherence","reason":"The facts provided are not unrelated; they are all centered around the weather study. A main point exists—showing the students' scientific process."},{"choice":"to tell a made-up adventure with a surprising ending","category":"wrong genre","reason":"This is a factual account of students measuring weather, not a creative story. There are no characters in a plot, and there is no fictional adventure."},"",{"choice":"to confuse readers about the topic","category":"incorrect intent","reason":"Authors write to share information, not to confuse the reader. The passage is written clearly to help the reader understand a specific sequence of events."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":130,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0131","version":3,"contentHash":"sha256:6993c14991a07105d74db245611cef593b5baca2f38bc394537714ea4479569d","question":"Read the passage. Grade 4 challenge passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper. Because the passage connects actions with results, readers can see why the recycling team helped the school waste less paper. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["The passage gives no examples or details.","The nurse checked the first-aid supplies after lunch.","The passage avoids the topic after the first sentence.","They placed blue bins in classrooms and reminded students to use both sides of paper."],"correct":3,"studyAid":{"definition":"Persuasive writing uses reasons, evidence, and actions to convince the reader that an idea or program is valuable and worth supporting.","example":"Persuasive: 'We should compost because it turns waste into soil for our garden.' Non-persuasive: 'I ate an apple for lunch today.'","strategyClue":"Look for sentences that show how a goal was achieved through specific, positive actions. Persuaders often provide these details to prove that an idea works.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They placed blue bins in classrooms and reminded students to use both sides of paper. This sentence provides evidence of specific actions taken to solve a problem, which is a key persuasive strategy used to show the effectiveness of the recycling program.","incorrect":[{"choice":"The passage gives no examples or details.","category":"factual accuracy error","reason":"This is incorrect because the passage is full of details, such as the use of blue bins and the advice to use both sides of the paper."},{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This sentence is not part of the passage provided and does not relate to the topic of recycling paper at school."},{"choice":"The passage avoids the topic after the first sentence.","category":"reading comprehension error","reason":"The passage continues to discuss recycling throughout every sentence; it does not shift the topic after the first sentence."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":131,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0132","version":3,"contentHash":"sha256:1b89c0f41be0c15b5e309f143efb3619f31cb02732e26a9238afb18d54c4985d","question":"Read the passage. Grade 4 challenge passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories. Because the passage connects actions with results, readers can see why the exhibit used artifacts and voices to teach local history. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich audience would most likely find this passage useful?","choices":["readers who want to learn about the topic","readers looking for a fantasy story with magic","readers studying a recipe for dessert","readers trying to learn a new song"],"correct":0,"studyAid":{"definition":"To determine the target audience, identify the passage's main purpose (to inform, entertain, or persuade) and the specific subject matter being discussed.","example":"A guide on how to build a birdhouse is for someone wanting to learn a craft; a myth about a thunder god is for someone wanting an entertaining story.","strategyClue":"Look at the subject matter in the text and ask yourself: 'Is this information teaching me about something real, telling a made-up story, or giving me instructions?' Match that purpose to the types of readers who seek out those specific goals.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage describes a museum exhibit focused on local history, artifacts, and memories, which are educational elements meant to inform an audience interested in historical facts.","incorrect":["",{"choice":"readers looking for a fantasy story with magic","category":"mismatched genre expectations","reason":"The passage discusses historical artifacts and real-life memories, not magical creatures or imaginary worlds found in fantasy stories."},{"choice":"readers studying a recipe for dessert","category":"inconsistent content focus","reason":"A recipe would list ingredients and cooking steps, but this passage focuses on museum exhibits, history, and learning about the past."},{"choice":"readers trying to learn a new song","category":"inconsistent content focus","reason":"Learning a song requires musical notes or lyrics, whereas this text focuses on history, visual artifacts, and storytelling, not musical performance."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":132,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0133","version":3,"contentHash":"sha256:ccafb625653ad1717d4d2a0075af467c9be6b608dc03d1974ba17bb9b12c7b26","question":"Read the passage. Grade 4 challenge passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course. Because the passage connects actions with results, readers can see why testing and revising helped the robotics club improve its robot. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to tell a made-up adventure with a surprising ending","to explain how testing improved a robot","to list unrelated facts without a main point","to confuse readers about the topic"],"correct":1,"studyAid":{"definition":"An author's purpose is the main reason why they write a text, such as to explain a process, persuade the reader, or tell a story.","example":"An instructional manual explains how something works; a newspaper article reports news; a fable teaches a moral lesson.","strategyClue":"Look at the sentences in the passage and ask yourself: 'Does this text describe how to do something, or does it try to entertain me?' Identify the core subject that all the sentences are discussing together.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how testing improved a robot. The passage describes a specific sequence of actions (testing and adjusting code) and a clear result (the robot's improvement), which is the definition of explaining a process.","incorrect":[{"choice":"to tell a made-up adventure with a surprising ending","category":"incorrect genre","reason":"This is a factual account of a process, not a story with characters or a plot twist. There are no elements of a fictional adventure here."},"",{"choice":"to list unrelated facts without a main point","category":"disorganized content","reason":"The sentences in this passage are highly related; they all focus on the specific steps the robotics club took to make their robot work better."},{"choice":"to confuse readers about the topic","category":"unclear intent","reason":"An author's purpose is rarely to confuse the reader. The text provides clear details and a logical flow to help the reader learn about the testing process."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":133,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0134","version":3,"contentHash":"sha256:febbd48ae35f0aaaf9da05034942b8e113e5a7588d9906c7e53ac4e9e26e8af0","question":"Read the passage. Grade 4 challenge passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal. Because the passage connects actions with results, readers can see why the breakfast cart helped more students start the day with food. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["The passage avoids the topic after the first sentence.","The science lab received new magnifying glasses.","The cart offered fruit, yogurt, and whole-grain muffins near the front door.","The passage gives no examples or details."],"correct":2,"studyAid":{"definition":"Persuasive writing uses facts, reasons, and examples to convince a reader to believe in an idea or support a specific action.","example":"Persuasive: 'Our school needs a garden because it helps us learn science.' Not persuasive: 'The school has a red brick wall.'","strategyClue":"Look for sentences that highlight positive outcomes or provide supporting evidence for a project; these are often used by authors to win the reader over to their point of view.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The cart offered fruit, yogurt, and whole-grain muffins near the front door. This sentence provides a specific detail that explains the benefit and availability of the solution, which helps persuade the reader that the breakfast cart is a positive and effective idea for the community.","incorrect":[{"choice":"The passage avoids the topic after the first sentence.","category":"factual error","reason":"This is incorrect because the passage continues to discuss the breakfast cart throughout the entire paragraph, explaining its benefits and suggesting it should be supported."},{"choice":"The science lab received new magnifying glasses.","category":"irrelevant information","reason":"This sentence is not present in the passage and does not relate to the topic of the breakfast cart or the author's argument."},"",{"choice":"The passage gives no examples or details.","category":"factual error","reason":"The passage actually provides several details, such as the types of food offered and the location of the cart, to show why it is a helpful project."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":134,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0135","version":3,"contentHash":"sha256:bc62fbf294d156a55781f61c236b1abd1cec03e7e265ad124aa28bfbfd196222","question":"Read the passage. Grade 4 challenge passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek. Because the passage connects actions with results, readers can see why trail signs helped visitors move safely and learn about nature. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich audience would most likely find this passage useful?","choices":["readers trying to learn a new song","readers looking for a fantasy story with magic","readers studying a recipe for dessert","people who care about outdoor spaces"],"correct":3,"studyAid":{"definition":"To identify an audience, look for the main topic and purpose of the text. Ask yourself, 'Who would actually use this information in their daily life?'","example":"A guide about car engines is for mechanics; a flyer for a new toy is for children; an article about plant growth is for gardeners.","strategyClue":"Highlight the keywords in the passage (like 'trail', 'rangers', and 'nature'). Match these words to the potential audience and choose the group that would actually care about those specific topics.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: people who care about outdoor spaces. The passage focuses on hiking trails, park markers, and nature, which directly interest individuals involved in outdoor recreation or environmental appreciation.","incorrect":[{"choice":"readers trying to learn a new song","category":"mismatched topic","reason":"This passage describes hiking trails and park features. There is no information about music, lyrics, or melodies, so it would not be helpful for a musician."},{"choice":"readers looking for a fantasy story with magic","category":"mismatched genre","reason":"The text is an informative description of park improvements. It contains facts about nature rather than imaginary elements like wizards, spells, or magical creatures."},{"choice":"readers studying a recipe for dessert","category":"mismatched content","reason":"A recipe needs ingredients and cooking instructions. This passage discusses trail signs and benches, which have nothing to do with baking or preparing food."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":135,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0136","version":3,"contentHash":"sha256:c7e71b58c741d15201755921d4efe9222147e753833ba0f4245675f54c903214","question":"Read the passage. Grade 5 foundation passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to explain how students cared for a garden","to tell a made-up adventure with a surprising ending","to list unrelated facts without a main point","to confuse readers about the topic"],"correct":0,"studyAid":{"definition":"The author's purpose is the reason why an author writes a piece: to inform, persuade, or entertain.","example":"A manual explains how to build a shelf (inform), a review argues a movie is bad (persuade), and a short story about a dragon is meant to (entertain).","strategyClue":"Look at the verbs used in the text—like 'watered,' 'recorded,' and 'moved'—and ask yourself if the author is showing you a series of real-world steps or creating a fantasy world.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students cared for a garden. The text details a specific sequence of actions—watering, measuring, and adjusting shade—all centered around the goal of maintaining a healthy school garden.","incorrect":["",{"choice":"to tell a made-up adventure with a surprising ending","category":"wrong text type","reason":"The passage describes real, routine tasks rather than a fictional story with dramatic plot points or a surprise ending."},{"choice":"to list unrelated facts without a main point","category":"lacks logical connection","reason":"The facts in the passage are highly related; they all describe steps taken to ensure the growth and health of the seedlings."},{"choice":"to confuse readers about the topic","category":"incorrect author intent","reason":"Authors write to inform, persuade, or entertain, not to intentionally confuse the reader. The passage provides clear, orderly steps."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":136,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0137","version":3,"contentHash":"sha256:9f206df73ef1c86b02e713c13b6bcc9752758affe20fad171fc74f7539452e14","question":"Read the passage. Grade 5 foundation passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books. The author presents the steps and results so readers understand how the process works.\n\nWhich clue best shows that the author wants to explain?","choices":["The cafeteria served tomato soup on Thursday.","They sorted returned books by call number before placing them on shelves.","The passage avoids the topic after the first sentence.","The passage gives no examples or details."],"correct":1,"studyAid":{"definition":"Expository writing explains a topic by providing clear, step-by-step information, facts, or instructions.","example":"A recipe for cookies, instructions on how to plant a seed, or a description of how a volcano erupts.","strategyClue":"Look for sentences that use sequence words or describe specific actions taken to complete a task. Ask yourself, 'Which sentence shows me exactly how something was done?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This sentence provides a specific, step-by-step description of an action, which demonstrates that the author's purpose is to explain the process of organizing the library.","incorrect":[{"choice":"The cafeteria served tomato soup on Thursday.","category":"irrelevant information","reason":"This sentence mentions a cafeteria and soup, which are not related to the passage about the library. It does not provide any information about the author's explanation."},"",{"choice":"The passage avoids the topic after the first sentence.","category":"false statement","reason":"The passage actually continues to describe the sorting process and the shelf labels. The author does not avoid the topic; instead, they provide clear details about it."},{"choice":"The passage gives no examples or details.","category":"false statement","reason":"The passage provides several specific details, such as sorting books by call number and making shelf labels, which helps the reader understand the library improvement process."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":137,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0138","version":3,"contentHash":"sha256:78dd8cb925cc9fd4feff7b0addfc92f2022423131b39a784f2c954d69ba40785","question":"Read the passage. Grade 5 foundation passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose. The author presents the steps and results so readers understand how the process works.\n\nWhich audience would most likely find this passage useful?","choices":["readers studying a recipe for dessert","readers looking for a fantasy story with magic","readers who want to learn about the topic","readers trying to learn a new song"],"correct":2,"studyAid":{"definition":"Informational texts present facts and procedures to help readers understand how something works or why something happens.","example":"A guide on planting seeds, an article about how electricity works, a manual for building a birdhouse.","strategyClue":"Look at the main subject of the paragraph and ask yourself if it is a real-life process or a creative story. Match the text's purpose to the audience that would benefit from that specific information.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides informational text about collecting rainwater, which is helpful for someone seeking to understand a specific process or science project.","incorrect":[{"choice":"readers studying a recipe for dessert","category":"incorrect text type","reason":"This passage describes a science process for gardening, not instructions or ingredients for making food like a dessert recipe."},{"choice":"readers looking for a fantasy story with magic","category":"mismatched genre","reason":"The passage is factual and realistic. It lacks elements of make-believe or magic found in fantasy literature."},"",{"choice":"readers trying to learn a new song","category":"incorrect purpose","reason":"This text explains a collection method for water; it does not contain lyrics, musical notes, or rhythmic instructions needed to learn a song."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":138,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0139","version":3,"contentHash":"sha256:83f7119507a394161ef6d4503412030009b9bbbccb71749ef76f7d6de3aaa994","question":"Read the passage. Grade 5 foundation passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to confuse readers about the topic","to tell a made-up adventure with a surprising ending","to list unrelated facts without a main point","to explain how students made a newspaper"],"correct":3,"studyAid":{"definition":"An author's purpose is the reason they wrote a text. Common purposes include to inform, to explain, to persuade, or to entertain.","example":"To inform: A report on dinosaurs. To explain: A recipe for cookies. To persuade: An essay on recycling.","strategyClue":"Look at the beginning and the end of the paragraph. Identify the common theme connecting the events described, then ask yourself if the author is telling a story, giving instructions, or trying to change your opinion.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students made a newspaper. The passage explicitly details the specific actions taken by the students, from interviewing and writing to checking facts and printing, which describes the process of creating the newspaper.","incorrect":[{"choice":"to confuse readers about the topic","category":"incorrect purpose","reason":"The passage is written in clear, chronological steps rather than complex or misleading language. Its goal is to provide information, not to cause confusion."},{"choice":"to tell a made-up adventure with a surprising ending","category":"wrong text type","reason":"This is a factual account of a school project, not a fictional story. There is no plot twist or adventure arc included in the text."},{"choice":"to list unrelated facts without a main point","category":"lack of coherence","reason":"The facts provided are all connected to the central theme of the school newspaper. They work together to show how the reporters completed their task."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":139,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0140","version":3,"contentHash":"sha256:a4079ca25ddacd682812c18fd755fdcdad5699e17905676dc0d6ff54c5f4ea01","question":"Read the passage. Grade 5 foundation passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["They filled ten bags with plastic wrappers, bottle caps, and broken fishing line.","The town band played a concert in the park.","The passage avoids the topic after the first sentence.","The passage gives no examples or details."],"correct":0,"studyAid":{"definition":"Persuasive writing uses evidence and reasons to convince the reader to believe something or to take action.","example":"Persuasive: 'We should compost because it reduces landfill waste.' vs. Informational: 'The city collects compost on Tuesdays.'","strategyClue":"Look for the sentence that provides specific, tangible proof to show that the author's suggested action is both possible and beneficial.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides specific, concrete evidence of the success of the clean-up, which helps persuade the reader that such efforts are effective and worthwhile.","incorrect":["",{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This detail is not in the passage. Always stick to the information provided in the text when evaluating an author's argument."},{"choice":"The passage avoids the topic after the first sentence.","category":"factually incorrect","reason":"This is incorrect because the passage continues to discuss the volunteers' actions and provides reasons why people should support such efforts."},{"choice":"The passage gives no examples or details.","category":"ignoring textual evidence","reason":"The passage provides specific details, such as the ten bags of trash and the specific types of waste collected, to support its message."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":140,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0141","version":3,"contentHash":"sha256:22dd287822b2fbeae2854f46dbae86ac5cad7edcca51d79b546e25fe891df398","question":"Read the passage. Grade 5 foundation passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich audience would most likely find this passage useful?","choices":["readers looking for a fantasy story with magic","readers who want to learn about the topic","readers studying a recipe for dessert","readers trying to learn a new song"],"correct":1,"studyAid":{"definition":"To identify the intended audience, look for the passage's main purpose (to inform, to entertain, or to persuade) and the topic it covers.","example":"A guide about caring for a puppy is for pet owners; a biography about an astronaut is for people interested in space.","strategyClue":"Ask yourself: 'What is the author trying to teach me?' Match the topic of the text to the group of people who would benefit from knowing that specific information.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual, instructional information about bicycle safety and community issues, which is helpful to anyone interested in learning about those real-world topics.","incorrect":[{"choice":"readers looking for a fantasy story with magic","category":"wrong genre","reason":"Fantasy stories involve imaginary creatures or magical powers. This passage is non-fiction because it discusses real-life safety instructions."},"",{"choice":"readers studying a recipe for dessert","category":"wrong topic","reason":"A recipe would explain how to bake food using ingredients and measurements. This passage focuses on traffic safety and community responsibility."},{"choice":"readers trying to learn a new song","category":"wrong purpose","reason":"Learning a song would require lyrics or musical notes. The text provides guidance on physical actions like riding bikes, not melody or rhythm."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":141,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0142","version":3,"contentHash":"sha256:1cb8c1d587d84edfedbfad4b0b41addf76957aa43961aff270520a1e6ef19780","question":"Read the passage. Grade 5 foundation passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to list unrelated facts without a main point","to tell a made-up adventure with a surprising ending","to explain how new bus routes helped a neighborhood","to confuse readers about the topic"],"correct":2,"studyAid":{"definition":"An author's purpose is the reason they wrote a text, usually to inform, persuade, entertain, or explain how something works.","example":"An encyclopedia entry informs, a persuasive essay tries to change your mind, and a mystery novel entertains.","strategyClue":"Ask yourself: 'Why did the author write this?' Look for words that show cause and effect, and see if the passage describes a real-life situation or a made-up story.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how new bus routes helped a neighborhood. The passage provides specific details about the planners' actions and the positive outcomes for the community, which shows an expository purpose.","incorrect":[{"choice":"to list unrelated facts without a main point","category":"unorganized information","reason":"The passage is not just a random list; all the sentences are connected by the central topic of transportation improvements and their results."},{"choice":"to tell a made-up adventure with a surprising ending","category":"fiction vs nonfiction","reason":"This passage is informative and based on real-world planning. It does not contain characters, a plot, or a narrative arc typical of a fictional story."},"",{"choice":"to confuse readers about the topic","category":"author's intent","reason":"Authors write to communicate information clearly, not to confuse the reader. This passage uses straightforward language to describe a process."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":142,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0143","version":3,"contentHash":"sha256:3a334741c4b80a65207613b6d02f662220e47a3f729d1e81fcfb3a2d0f951dd3","question":"Read the passage. Grade 5 foundation passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich clue best shows that the author wants to describe?","choices":["The passage gives no examples or details.","A math poster showed different kinds of triangles.","The passage avoids the topic after the first sentence.","Actors practiced lines while stage crew members painted scenery and tested lights."],"correct":3,"studyAid":{"definition":"Descriptive writing uses specific nouns and verbs to paint a clear picture for the reader, showing exactly what is happening instead of just telling them.","example":"Telling: 'He walked to the store.' Showing: 'He sprinted down the sidewalk, clutching his grocery list.'","strategyClue":"Look for the sentence that contains the most 'action' verbs and concrete objects, as these are the tools authors use to help you visualize a scene.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence provides specific sensory details and actions that help the reader visualize exactly what was happening behind the scenes during the rehearsal.","incorrect":[{"choice":"The passage gives no examples or details.","category":"factual observation error","reason":"This is incorrect because the passage is full of descriptive details, such as the stage crew painting scenery and testing lights, which directly help the reader form a mental picture."},{"choice":"A math poster showed different kinds of triangles.","category":"irrelevant information inclusion","reason":"This information is not mentioned in the text at all; you must look for clues that exist within the provided passage about the play."},{"choice":"The passage avoids the topic after the first sentence.","category":"comprehension of structure","reason":"This choice is incorrect because the sentences following the first one continue to explain the specific actions taken by the actors and crew members to support the topic of teamwork."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":143,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0144","version":3,"contentHash":"sha256:0d9edd03686d4cfaf6bd65e219a2d60c485c4470836ecc6cdc2b940678713805","question":"Read the passage. Grade 5 foundation passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds. The author presents the steps and results so readers understand how the process works.\n\nWhich audience would most likely find this passage useful?","choices":["readers who want to learn about the topic","readers looking for a fantasy story with magic","readers studying a recipe for dessert","readers trying to learn a new song"],"correct":0,"studyAid":{"definition":"An author's purpose is the reason they wrote a text, such as to inform, to entertain, or to persuade.","example":"A news report informs, a fairy tale entertains, and an advertisement persuades.","strategyClue":"Identify the main topic of the passage first. Ask yourself: 'Is the text providing facts about a real-world process, or is it trying to make me laugh or imagine things?' Match that goal to your reading goal.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides facts about composting, which is a process, making it a perfect fit for someone seeking information or trying to learn how something works.","incorrect":["",{"choice":"readers looking for a fantasy story with magic","category":"wrong genre purpose","reason":"Fantasy stories involve make-believe characters and magical elements. This passage describes a real-world science process, so it would not satisfy someone looking for fiction."},{"choice":"readers studying a recipe for dessert","category":"mismatched content goal","reason":"A recipe provides ingredients and steps to make food you can eat. This passage is about recycling food scraps, not cooking, so it does not provide the instructions needed for a dessert."},{"choice":"readers trying to learn a new song","category":"mismatched instructional format","reason":"Learning a song requires lyrics or musical notation. The passage explains an environmental science process, so it contains no melody or rhythm to help a reader learn music."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":144,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0145","version":3,"contentHash":"sha256:40bc11f40a760433520ac5a4668f03034233ca521df892f240a96148a43d9099","question":"Read the passage. Grade 5 foundation passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to tell a made-up adventure with a surprising ending","to explain how students studied weather","to list unrelated facts without a main point","to confuse readers about the topic"],"correct":1,"studyAid":{"definition":"An author's purpose is the reason they wrote a text. Common purposes include to inform, to entertain, to explain, or to persuade.","example":"An encyclopedia entry informs, a fable entertains, and a science report explains a process.","strategyClue":"Look at the actions described in the text and ask yourself: 'Is the author trying to tell a story, give me information, or explain how something works?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how students studied weather. The passage details the specific actions taken by the students—tracking, measuring, and charting data—to show the reader the methodology and outcomes of their observation process.","incorrect":[{"choice":"to tell a made-up adventure with a surprising ending","category":"incorrect text type","reason":"The passage is factual and describes a scientific process, not a creative story with characters, plot twists, or a fictional adventure."},"",{"choice":"to list unrelated facts without a main point","category":"disorganized information","reason":"The information provided is not random; each sentence focuses on the students' weather study, forming a coherent report rather than an unrelated list."},{"choice":"to confuse readers about the topic","category":"misunderstanding author intent","reason":"Authors write to inform, persuade, or entertain. The author's goal here is to be clear and helpful, not to make the topic harder for the reader to understand."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":145,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0146","version":3,"contentHash":"sha256:7f7287b211ef53d5b255f0bdf33be75e416e1ca80c3bea4e3fb8b206b80930c9","question":"Read the passage. Grade 5 foundation passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["The passage avoids the topic after the first sentence.","The nurse checked the first-aid supplies after lunch.","They placed blue bins in classrooms and reminded students to use both sides of paper.","The passage gives no examples or details."],"correct":2,"studyAid":{"definition":"Persuasive writing uses evidence, examples, and logical reasons to convince the reader to think or act in a certain way.","example":"Persuasive: 'You should recycle because it saves trees.' Non-persuasive: 'Recycling happens on Tuesdays.'","strategyClue":"Look for the sentence that provides a concrete action or positive outcome. Authors use these specific details to 'prove' that an idea is effective and worth following.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They placed blue bins in classrooms and reminded students to use both sides of paper. This sentence shows the author is presenting specific actions taken to solve a problem, which is a hallmark of persuasive writing aimed at encouraging readers to adopt similar habits.","incorrect":[{"choice":"The passage avoids the topic after the first sentence.","category":"factual accuracy error","reason":"This is incorrect because the passage stays focused on recycling throughout, providing multiple details about how the team reduced waste and why others should join in."},{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This sentence is not part of the passage at all. It does not relate to the topic of recycling or the author's argument about school waste."},"",{"choice":"The passage gives no examples or details.","category":"misreading the text","reason":"This is incorrect because the passage provides clear examples, such as 'placed blue bins' and 'use both sides of paper', to support its point."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":146,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0147","version":3,"contentHash":"sha256:05359febac681deb0bc88d151450beb8c65332c360242cb59cf1434c593fb0ec","question":"Read the passage. Grade 5 foundation passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich audience would most likely find this passage useful?","choices":["readers trying to learn a new song","readers looking for a fantasy story with magic","readers studying a recipe for dessert","readers who want to learn about the topic"],"correct":3,"studyAid":{"definition":"To determine the audience of a passage, identify the main topic and purpose: if the text gives facts or explains a real subject, it is meant for someone looking to gain knowledge.","example":"A guide about planets is for people learning science; a story about a dragon is for people who enjoy fiction; a manual about fixing a sink is for people who need to repair something.","strategyClue":"Look at the subject matter: list the key nouns (history, tools, photographs) and ask yourself if those items are meant to entertain, teach, or persuade. Then, match that goal to the most logical reader.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: readers who want to learn about the topic. The passage provides factual information about history, tools, and museum exhibits, which is specifically designed to educate the reader about a real-world subject.","incorrect":[{"choice":"readers trying to learn a new song","category":"irrelevant content type","reason":"The passage describes museum exhibits and history, not musical notes, lyrics, or melodies, so it would not help someone learn a song."},{"choice":"readers looking for a fantasy story with magic","category":"wrong genre expectations","reason":"This passage focuses on real historical objects and accounts from elders. It does not contain the made-up characters, spells, or magical settings required for a fantasy story."},{"choice":"readers studying a recipe for dessert","category":"mismatched instructional goal","reason":"A recipe needs ingredients and cooking steps. This text provides historical background information, which does not teach a reader how to prepare food."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":147,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0148","version":3,"contentHash":"sha256:69de4db003f59397cd04046aafd4ce454e3eda9f615c42f7af5433bcfaa203fb","question":"Read the passage. Grade 5 foundation passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course. The author presents the steps and results so readers understand how the process works.\n\nWhat is the author's main purpose?","choices":["to explain how testing improved a robot","to tell a made-up adventure with a surprising ending","to list unrelated facts without a main point","to confuse readers about the topic"],"correct":0,"studyAid":{"definition":"The author's purpose is the reason why someone writes a text. It is usually to inform (explain), persuade (convince), or entertain (tell a story).","example":"Inform: How to bake a cake. Persuade: Why you should adopt a pet. Entertain: A story about a dragon.","strategyClue":"Look at the passage as a whole. Ask yourself, 'Is the author telling a story, giving an opinion, or describing how something works?' Look for verbs like 'explained' or 'showed' to identify the main focus.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: to explain how testing improved a robot. The passage focuses on a sequence of events—testing the robot, noticing errors, adjusting the code, and finding better speeds—to show the reader how a specific process led to improvement.","incorrect":["",{"choice":"to tell a made-up adventure with a surprising ending","category":"incorrect genre identification","reason":"This passage is informative and based on a process, not a fictional story. There is no suspenseful plot, characters, or sudden twist typically found in an adventure story."},{"choice":"to list unrelated facts without a main point","category":"missing main idea","reason":"The sentences in the passage are all closely related to one main point: the process of testing and improving a robot. They are not random facts."},{"choice":"to confuse readers about the topic","category":"incorrect author intent","reason":"The author's goal is to communicate clearly so the reader understands how the robot was improved, not to make the topic harder to understand."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":148,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0149","version":3,"contentHash":"sha256:c15e06aa5aff03f8b91eaddd3d894fca15b4caea71dc7b8f1f007a0666c4b0e2","question":"Read the passage. Grade 5 foundation passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal. The author adds that more people should support efforts like this because they solve real community problems.\n\nWhich clue best shows that the author wants to persuade?","choices":["The science lab received new magnifying glasses.","The cart offered fruit, yogurt, and whole-grain muffins near the front door.","The passage avoids the topic after the first sentence.","The passage gives no examples or details."],"correct":1,"studyAid":{"definition":"Persuasive writing includes an author's opinion and evidence, such as facts or reasons, to show why they believe something is good or important.","example":"Persuasive: 'We should have recess daily because it helps us learn better.' Informational: 'Recess is a scheduled break during the school day.'","strategyClue":"Look for the sentence that explains the value or the 'why' behind the breakfast program. Authors use positive supporting details to convince the reader that an idea is helpful.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The cart offered fruit, yogurt, and whole-grain muffins near the front door. This sentence provides specific evidence of the program's success, which supports the author's argument that the initiative is beneficial and worth supporting.","incorrect":[{"choice":"The science lab received new magnifying glasses.","category":"irrelevant information provided","reason":"This detail is not mentioned in the text provided. When looking for persuasive clues, focus only on the information given in the passage."},"",{"choice":"The passage avoids the topic after the first sentence.","category":"factual reading error","reason":"The passage continues to discuss the breakfast cart throughout, providing details about what is served and why it is a helpful solution."},{"choice":"The passage gives no examples or details.","category":"inaccurate text analysis","reason":"The passage actually includes several specific details about the types of food offered and where the cart is located, which helps persuade the reader."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":149,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-authors-purpose-q0150","version":3,"contentHash":"sha256:129bbe5679cdd2517234e5bfdb52eda488c6f6d5fc6d9c0e3b36d7d8f3d11636","question":"Read the passage. Grade 5 foundation passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek. The author includes specific sights, parts, and actions so readers can picture the scene clearly.\n\nWhich audience would most likely find this passage useful?","choices":["readers studying a recipe for dessert","readers looking for a fantasy story with magic","people who care about outdoor spaces","readers trying to learn a new song"],"correct":2,"studyAid":{"definition":"To identify an intended audience, determine the main topic of the text and decide what kind of person would benefit from or enjoy that specific information.","example":"A guide on fixing cars is for mechanics; a poem about stars is for poetry lovers.","strategyClue":"Highlight the key nouns and activities mentioned in the text, then ask yourself: 'Who would spend their time reading about these specific things?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: people who care about outdoor spaces. The passage provides descriptive details about a hiking trail, including signs, trees, and rest areas, which directly relates to the interests of hikers and nature enthusiasts.","incorrect":[{"choice":"readers studying a recipe for dessert","category":"irrelevant topic content","reason":"This passage describes a hiking trail, not instructions for cooking or ingredients for a dessert."},{"choice":"readers looking for a fantasy story with magic","category":"mismatched literary genre","reason":"The text focuses on real-world park improvements like signs and benches rather than magical creatures or fictional adventures."},"",{"choice":"readers trying to learn a new song","category":"incompatible text purpose","reason":"The passage contains information about a physical environment, not lyrics, musical notes, or singing instructions."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["author's purpose","point of view","author's craft"],"standards":["RI.2-6.6"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-authors-purpose","sequence":150,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI.2-6.6","RI/RL.2-6.1","RI/RL.2-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, with 15 exact-match questions for every supported grade and difficulty"}};
  const bank = window.QUESTION_BANK = window.QUESTION_BANK || {};
  const existing = bank["reading-comprehension-authors-purpose"];
  if (existing && Array.isArray(existing.questions)) {
    const seen = new Set(existing.questions.map(question => question && question.id));
    chunkSet.questions.forEach(question => {
      if (!seen.has(question && question.id)) existing.questions.push(question);
    });
  } else {
    bank["reading-comprehension-authors-purpose"] = chunkSet;
  }
})();
